WITH filtered AS (SELECT id, store_id, sale_date, revenue, ROUND(units, 0) AS units_rounded, DATE_TRUNC('week', sale_date) AS sale_date_period FROM store_sales WHERE sale_date >= DATE '2023-04-02'), latest AS (SELECT * FROM (SELECT *, RANK() OVER (PARTITION BY store_id ORDER BY sale_date DESC) AS rn FROM filtered) x WHERE rn = 1), joined AS (SELECT a.*, s.opened_date, s.city FROM latest a LEFT JOIN stores s ON a.store_id = s.id), with_windows AS (SELECT *, LEAD(revenue) OVER (PARTITION BY store_id ORDER BY units_rounded, id) AS next_revenue, LEAD(units_rounded) OVER (PARTITION BY store_id ORDER BY units_rounded, id) AS next_units_rounded, ROW_NUMBER() OVER (PARTITION BY store_id ORDER BY units_rounded, id) AS event_seq FROM joined WHERE revenue > 1800) SELECT store_id, MIN(sale_date_period) AS first_sale_date_period, MAX(next_units_rounded) FILTER (WHERE city = 'Berlin') AS berlin_max_next_units_rounded, SUM(next_units_rounded) FILTER (WHERE city = 'Singapore') AS singapore_total_next_units_rounded, COUNT(CASE WHEN city = 'Chiang Mai' THEN 1 END) AS chiang_mai_count, COUNT(CASE WHEN city = 'New York' THEN 1 END) AS new_york_count FROM with_windows GROUP BY store_id;
